import random
import sys

import pygame

WIDTH, HEIGHT = 800, 600
FPS = 60
WHITE = (255, 255, 255)
BLACK = (15, 15, 15)

PADDLE_W, PADDLE_H, PADDLE_SPEED = 12, 90, 7
BALL_SIZE, BALL_SPEED, SPEED_UP, MAX_SPEED = 14, 6, 0.5, 14
WIN_SCORE = 5
SERVE_DELAY = 45


class Paddle:
    def __init__(self, x):
        self.rect = pygame.Rect(x, (HEIGHT - PADDLE_H) // 2, PADDLE_W, PADDLE_H)

    def move(self, dy):
        self.rect.y = max(0, min(HEIGHT - PADDLE_H, self.rect.y + dy))


class Ball:
    def __init__(self):
        self.rect = pygame.Rect(0, 0, BALL_SIZE, BALL_SIZE)
        self.reset(random.choice((-1, 1)))

    def reset(self, direction):
        self.rect.center = (WIDTH // 2, HEIGHT // 2)
        self.vx = direction * BALL_SPEED
        self.vy = random.uniform(-0.7, 0.7) * BALL_SPEED
        self.delay = SERVE_DELAY


def blit_text(surface, text, font, center):
    img = font.render(text, True, WHITE)
    surface.blit(img, img.get_rect(center=center))


def draw_center_line(surface):
    for y in range(10, HEIGHT, 30):
        pygame.draw.rect(surface, WHITE, (WIDTH // 2 - 2, y, 4, 16))


def play(screen, fonts, clock):
    font_big, font_small = fonts
    left = Paddle(30)
    right = Paddle(WIDTH - 30 - PADDLE_W)
    ball = Ball()
    score = [0, 0]

    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT or (
                event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE
            ):
                pygame.quit()
                sys.exit()

        keys = pygame.key.get_pressed()
        if keys[pygame.K_w]:
            left.move(-PADDLE_SPEED)
        if keys[pygame.K_s]:
            left.move(PADDLE_SPEED)
        if keys[pygame.K_UP]:
            right.move(-PADDLE_SPEED)
        if keys[pygame.K_DOWN]:
            right.move(PADDLE_SPEED)

        if ball.delay > 0:
            ball.delay -= 1
        else:
            ball.rect.x += round(ball.vx)
            ball.rect.y += round(ball.vy)

            if ball.rect.top <= 0:
                ball.rect.top = 0
                ball.vy = abs(ball.vy)
            elif ball.rect.bottom >= HEIGHT:
                ball.rect.bottom = HEIGHT
                ball.vy = -abs(ball.vy)

            if ball.vx < 0 and ball.rect.colliderect(left.rect):
                ball.rect.left = left.rect.right
                ball.vx = min(abs(ball.vx) + SPEED_UP, MAX_SPEED)
                ball.vy = (ball.rect.centery - left.rect.centery) / (PADDLE_H / 2) * BALL_SPEED
            elif ball.vx > 0 and ball.rect.colliderect(right.rect):
                ball.rect.right = right.rect.left
                ball.vx = -min(abs(ball.vx) + SPEED_UP, MAX_SPEED)
                ball.vy = (ball.rect.centery - right.rect.centery) / (PADDLE_H / 2) * BALL_SPEED

            if ball.rect.right < 0:
                score[1] += 1
                ball.reset(-1)
            elif ball.rect.left > WIDTH:
                score[0] += 1
                ball.reset(1)

            if score[0] >= WIN_SCORE or score[1] >= WIN_SCORE:
                return ("Player 1" if score[0] >= WIN_SCORE else "Player 2"), score

        screen.fill(BLACK)
        draw_center_line(screen)
        blit_text(screen, str(score[0]), font_big, (WIDTH // 4, 50))
        blit_text(screen, str(score[1]), font_big, (3 * WIDTH // 4, 50))
        pygame.draw.rect(screen, WHITE, left.rect)
        pygame.draw.rect(screen, WHITE, right.rect)
        pygame.draw.rect(screen, WHITE, ball.rect)
        if ball.delay > 0:
            blit_text(screen, "Get ready...", font_small, (WIDTH // 2, HEIGHT - 40))
        pygame.display.flip()
        clock.tick(FPS)


def game_over(screen, fonts, winner, score):
    font_big, font_small = fonts
    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT or (
                event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE
            ):
                pygame.quit()
                sys.exit()
            if event.type == pygame.KEYDOWN and event.key == pygame.K_r:
                return True
        screen.fill(BLACK)
        blit_text(screen, f"{winner} wins!", font_big, (WIDTH // 2, HEIGHT // 2 - 60))
        blit_text(screen, f"{score[0]} - {score[1]}", font_big, (WIDTH // 2, HEIGHT // 2))
        blit_text(screen, "Press R to play again, ESC to quit",
                  font_small, (WIDTH // 2, HEIGHT // 2 + 70))
        pygame.display.flip()


def main():
    pygame.init()
    screen = pygame.display.set_mode((WIDTH, HEIGHT))
    pygame.display.set_caption("Pong  |  P1: W/S   P2: Arrow Up/Down")
    fonts = (pygame.font.SysFont(None, 64, bold=True), pygame.font.SysFont(None, 32))
    clock = pygame.time.Clock()
    while True:
        winner, score = play(screen, fonts, clock)
        if not game_over(screen, fonts, winner, score):
            break
    pygame.quit()


if __name__ == "__main__":
    main()
